/// <summary>
/// The <c>ALNWHSProcessGuideChangePrinterController</c> class is the controller class to run the change printer process
/// </summary>
[
    WHSWorkExecuteMode(WHSWorkExecuteMode::AVAChangePrinter)
]
class AVAWHSProcessGuideChangePrinterController extends ProcessGuideController
{
}

Method.Source:
protected final ProcessGuideNavigationRoute initializeNavigationRoute()
{
    ProcessGuideNavigationRoute navigationRoute = new ProcessGuideNavigationRoute();

    navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePromptCurrentPrinterStep), classStr(AVAWHSProcessGuidePromptChangePrinterStep));
    navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuidePromptChangePrinterStep), classStr(AVAWHSProcessGuideDoChangePrinterStep));
    navigationRoute.addFollowingStep(classStr(AVAWHSProcessGuideDoChangePrinterStep), classStr(AVAWHSProcessGuidePromptCurrentPrinterStep));

    return navigationRoute;
}
